def btw(bedrag, tarief=0.21):
    """Geef de btw over bedrag bij het opgegeven tarief."""
    return round(bedrag * tarief, 2)

print(btw(200))                    # tarief krijgt de default
print(btw(200, 0.09))              # positioneel argument
print(btw(tarief=0.09, bedrag=50)) # keyword-argumenten

def gemiddelde(waarden: list[float]) -> float:
    """Geef het rekenkundig gemiddelde van een niet-lege lijst."""
    return sum(waarden) / len(waarden)

def lijkt_op_email(adres: str) -> bool:
    """Grove controle op een e-mailadres, geen volledige validatie."""
    return adres.count("@") == 1 and "." in adres.split("@")[1]

print(gemiddelde([6.0, 7.5, 9.0]))
print(lijkt_op_email("sara@voorbeeld.nl"), lijkt_op_email("sara@voorbeeld"))

def is_geldig_telefoonnummer(nummer: str) -> bool:
    """Alleen cijfers, spaties en + zijn toegestaan."""
    if nummer == "":
        return False
    for teken in nummer:
        if teken not in "0123456789 +":
            return False
    return True

print(is_geldig_telefoonnummer("+31 6 1234"))
print(is_geldig_telefoonnummer("06-1234"))

